module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the flip-flop outputs
    wire f0, f1, f2;

    // D Flip-Flops (reset to zero initially)
    // Using 'reg' type with initial values to ensure l-value compatibility
    // and positive-edge triggered behavior. The initial values ensure
    // the flip-flops start in the reset state (0).
    reg f0, f1, f2;

    initial begin
        f0 = 1'b0;
        f1 = 1'b0;
        f2 = 1'b0;
    end

    always_ff @(posedge clk) begin
        // Flip-flop 0: D input is XOR of x and its own output f0
        // The second input of the XOR gate is f0 itself.
        // Thus: D0 = x ^ f0
        f0 <= x ^ f0;

        // Flip-flop 1: D input is AND of x and complemented output f1'
        // The second input of the AND gate is ~f1.
        // Thus: D1 = x & ~f1
        f1 <= x & ~f1;

        // Flip-flop 2: D input is OR of x and complemented output f2'
        // The second input of the OR gate is ~f2.
        // Thus: D2 = x | ~f2
        f2 <= x | ~f2;
    end

    // Three-input NOR gate
    // Output Z is the NOR of f0, f1, and f2
    assign z = ~(f0 | f1 | f2);

endmodule

