    always @(posedge x) begin
        case (state)
            S_IDLE: begin
                if (y == 1'b0) begin
                    state <= S_A;
                    enable <= 1'b1;
                end else begin
                    state <= S_IDLE;
                    enable <= 1'b0;
                end
