module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding
    typedef enum logic [2:0] {
        STATE_A  = 3'b000,
        STATE_B  = 3'b001,
        STATE_C  = 3'b010,
        STATE_D  = 3'b011,
        STATE_E  = 3'b100,
        STATE_F  = 3'b101,
        STATE_G  = 3'b110
    } state_type;

    state_type state, next_state;

    // Outputs registered
    logic f_reg, g_reg;
    assign f = f_reg;
    assign g = g_reg;

    // Next-state logic (combinational)
    always_comb begin
        next_state = state;  // default: stay in current state
        f_reg     = 1'b0;    // default: f low
        g_reg     = 1'b0;    // default: g low

        case (state)
            STATE_A: begin
                // As long as resetn is asserted (low), stay in A.
                // When resetn is de-asserted, after the next clock edge
                // the FSM has to set output f to 1 for one clock cycle.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                end else begin
                    // De-asserted reset: go to state B, f pulses high next cycle
                    next_state = STATE_B;
                    f_reg      = 1'b1;  // f will be valid after the clock edge
                end
            end

            STATE_B: begin
                // After setting f high in STATE_A, we transition to C.
                // Now monitor x for the sequence 1, 0, 1.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    // Sample x
                    if (x == 1'b1) begin
                        // First '1' of the sequence detected
                        next_state = STATE_C;
                    end else begin
                        // Not the expected first '1'; stay in B until we see a 1.
                        next_state = STATE_B;
                    end
                end
            end

            STATE_C: begin
                // We have seen x=1. Now expect x=0.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    if (x == 1'b0) begin
                        // Second step: 0 detected, go to state D expecting final 1
                        next_state = STATE_D;
                    end else begin
                        // x is 1 again; reset the sequence (go back to B or A)
                        next_state = STATE_B;
                    end
                end
            end

            STATE_D: begin
                // We have seen 1,0. Now expect x=1 to complete the sequence.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    if (x == 1'b1) begin
                        // Sequence 1,0,1 complete -> set g high next cycle
                        next_state = STATE_E;
                        g_reg      = 1'b1;   // g will be valid after clock
                    end else begin
                        // Sequence incomplete; go back to start
                        next_state = STATE_A;
                        f_reg      = 1'b0;
                        g_reg      = 1'b0;
                    end
                end
            end

            // STATE_E: g is high; monitor y within at most two clock cycles
            STATE_E: begin
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    // Check y
                    if (y == 1'b1) begin
                        // y became 1 within the allowed window -> maintain g=1
                        // Stay in STATE_E indefinitely (until reset)
                        next_state = STATE_E;
                        g_reg      = 1'b1;
                    end else begin
                        // y is 0; we need to count clock cycles.
                        // Transition to STATE_F for the second-cycle check.
                        next_state = STATE_F;
                    end
                end
            end

            STATE_F: begin
                // Second cycle check: if y is 1 now, maintain g.
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    if (y == 1'b1) begin
                        // y became 1 within the two-cycle window
                        next_state = STATE_E;
                        g_reg      = 1'b1;
                    end else begin
                        // y still 0 after two cycles -> g = 0 permanently
                        next_state = STATE_G;
                        g_reg      = 1'b0;
                    end
                end
            end

            STATE_G: begin
                // g stuck low until reset
                if (~resetn) begin
                    next_state = STATE_A;
                    f_reg      = 1'b0;
                    g_reg      = 1'b0;
                end else begin
                    next_state = STATE_G;
                    g_reg      = 1'b0;
                end
            end

            default: next_state = STATE_A;
        endcase
    end

    // Sequential logic: state register update on positive edge of clk
    always_ff @(posedge clk or negedge resetn) begin
        if (~resetn) begin
            state <= STATE_A;
            f_reg <= 1'b0;
            g_reg <= 1'b0;
        end else begin
            state <= next_state;
            // f_reg and g_reg are already updated in the combinational block,
            // but we also capture them here to make the pipeline explicit
            // if needed. Since we use non-blocking assignments in the
            // always_comb, the registers update automatically.
        end
    end

endmodule

